def drawings(c,base,arch,rs,es,systems,labelled,arrows=False,offsets=None):
    draw_base(c,base,arch);offsets=offsets or {}
    for r in rs:
        if r['system'] not in systems: continue
        sys=r['system'];p=r['points'];tone=PALETTE[sys]
        path(c,p,tone,.68 if sys in ['CABLE','CW','HW'] else 1.6,(3,2) if sys in ['HW','FLEX','CABLE','COND','EXH'] else ())
        if arrows:
            for a,b in zip(p,p[1:]):arrow(c,a,b,tone)
    for e in es:
        if e['system'] not in systems: continue
        sys=e['system'];tone=PALETTE[sys]
        dx,dy=offsets.get(e['id'],(5,4));label=e['id'] if sys in labelled else ''
        dot(c,e['point'],label,tone,dx,dy,2.6)
def put_link(c,x,y,url,label):
    txt(c,x,y,label,11,'Arm',TEAL)
    c.linkURL(url,(x,y-2,x+pdfmetrics.stringWidth(label,'Arm',11),y+14),relative=0)
